}
@keyframes chrt-line-axes-draw{to{stroke-dashoffset:0}}
.chrt-line-axes-dot{
  fill:var(--cl-bg);stroke:var(--cl-line);stroke-width:1.5;opacity:0;
  animation:chrt-line-axes-pop .42s cubic-bezier(.34,1.56,.64,1) forwards;
  animation-delay:calc(.22s + var(--i) * .052s);
