.chrt-line-axes-focus{fill:var(--cl-line);stroke:var(--cl-bg);stroke-width:2;opacity:0;transition:opacity .16s,transform .18s cubic-bezier(.22,1,.36,1)}
.chrt-line-axes--live .chrt-line-axes-cross,.chrt-line-axes--live .chrt-line-axes-focus{opacity:1}
