.chrt-line-axes--below .chrt-line-axes-tip{transform:translate(-50%,30%) scale(.92)}
.chrt-line-axes--live .chrt-line-axes-tip{opacity:1;transform:translate(-50%,-128%) scale(1)}
.chrt-line-axes--live.chrt-line-axes--below .chrt-line-axes-tip{transform:translate(-50%,30%) scale(1)}
.chrt-line-axes-tipv{font-size:11px;font-weight:700;color:var(--cl-line);font-variant-numeric:tabular-nums}
