@media (prefers-reduced-motion:reduce){
  .chrt-line-axes-line{animation:none;stroke-dashoffset:0}
  .chrt-line-axes-dot{animation:none;opacity:1}
  .chrt-line-axes-cross,.chrt-line-axes-focus,.chrt-line-axes-tip{transition:none}
