  var yy=y(v);
  grid.appendChild(mk("line",v===0?"chrt-bar-grouped-base":"chrt-bar-grouped-gl",{x1:X0,y1:yy,x2:292,y2:yy}));
  var t=mk("text","chrt-bar-grouped-t",{x:X0-6,y:yy+3,"text-anchor":"end"});
  t.textContent=v;grid.appendChild(t);
});
CAT.forEach(function(c,gi){
  var cx=X0+GW*gi+GW/2;
  var lab=mk("text","chrt-bar-grouped-t",{x:cx,y:95,"text-anchor":"middle"});
  lab.textContent=c;grid.appendChild(lab);
  for(var s=0;s<2;s++){
    var bx=s===0?cx-16:cx+2;
    var g=mk("g","chrt-bar-grouped-b",{});
    var v=S[s][gi],h=BASE-y(v);
