 [268,255,262,240,251,233,245,228,236,222,230,214,240,225,219,214],
 [.30,.28,.33,.31,.36,.34,.30,.38,.35,.40,.37,.42,.39,.44,.41,.42],
 [1900,1820,1750,1690,1600,1655,1520,1480,1390,1440,1330,1280,1210,1260,1180,1200]
];
var DETAIL=[
 "Checkout p95 · peak 268 ms",
 "Error rate · peak 0.44%",
 "Queue depth · peak 1.9k"
];
var items=root.querySelectorAll(".chrt-spark-row-item");
var lis=root.querySelectorAll(".chrt-spark-row-li");
var sub=root.querySelector(".chrt-spark-row-sub");
var W=72,H=24,PAD=3;
for(var r=0;r<items.length;r++){
  (function(i){
    var el=items[i],d=DATA[i];
    var lo=Math.min.apply(null,d),hi=Math.max.apply(null,d),span=(hi-lo)||1;
    var line=el.querySelector(".chrt-spark-row-line");
    var area=el.querySelector(".chrt-spark-row-area");
    var cap=el.querySelector(".chrt-spark-row-cap");
    var pts=d.map(function(v,j){
      return [(j*(W-2)/(d.length-1)+1),(H-PAD-(v-lo)/span*(H-PAD*2))];
    });
    var path=pts.map(function(p,j){return (j?"L":"M")+p[0].toFixed(1)+","+p[1].toFixed(1);}).join("");
    line.setAttribute("d",path);
    area.setAttribute("d",path+"L"+pts[pts.length-1][0].toFixed(1)+","+H+"L"+pts[0][0].toFixed(1)+","+H+"Z");
    cap.setAttribute("cx",pts[pts.length-1][0]);
    cap.setAttribute("cy",pts[pts.length-1][1]);
    line.style.setProperty("--i",i);
    el.addEventListener("click",function(){
      var was=el.getAttribute("aria-pressed")==="true";
      for(var j=0;j<items.length;j++){items[j].setAttribute("aria-pressed","false");}
      if(was){sub.textContent="last 24h · 5m buckets";return;}
      el.setAttribute("aria-pressed","true");
      sub.textContent=DETAIL[i];
      line.style.animation="none";
      void line.getBoundingClientRect();
      line.style.animation="";
    });
  })(r);
}
requestAnimationFrame(function(){root.classList.add("chrt-spark-row--in");});

css:
.chrt-cal-heatmap{
  --ch-ink:#E6F0EA; --ch-dim:rgba(230,240,234,.45);
  --ch-l0:rgba(255,255,255,.06); --ch-l1:#1E5B45; --ch-l2:#2F8A62; --ch-l3:#46B87C; --ch-l4:#7BE8A8;
  box-sizing:border-box;width:100%;margin:0;padding:10px 12px 8px;
  font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--ch-ink);background:linear-gradient(180deg,#0F1714,#0A0D0C);
  border:1px solid rgba(255,255,255,.08);border-radius:14px;
}
.chrt-cal-heatmap-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.chrt-cal-heatmap-title{font-size:11px;font-weight:600}
.chrt-cal-heatmap-count{font-size:9.5px;color:var(--ch-dim);font-variant-numeric:tabular-nums;white-space:nowrap}
.chrt-cal-heatmap-wrap{position:relative;margin-top:3px;border-radius:8px;outline:none}
.chrt-cal-heatmap-wrap:focus-visible{box-shadow:0 0 0 2px rgba(123,232,168,.65)}
.chrt-cal-heatmap-svg{display:block;width:100%;height:auto;overflow:visible}
.chrt-cal-heatmap-t{fill:var(--ch-dim);font-size:6.5px;font-family:inherit}
.chrt-cal-heatmap-c{
  opacity:0;transform:scale(.4);transform-box:fill-box;transform-origin:center;
  transition:opacity .32s ease calc(var(--i) * 26ms),transform .42s cubic-bezier(.34,1.56,.64,1) calc(var(--i) * 26ms),stroke .15s;
  stroke:transparent;stroke-width:1;
}
.chrt-cal-heatmap--in .chrt-cal-heatmap-c{opacity:1;transform:none}
.chrt-cal-heatmap-c--l0{fill:var(--ch-l0)}
.chrt-cal-heatmap-c--l1{fill:var(--ch-l1)}
.chrt-cal-heatmap-c--l2{fill:var(--ch-l2)}
.chrt-cal-heatmap-c--l3{fill:var(--ch-l3)}
.chrt-cal-heatmap-c--l4{fill:var(--ch-l4)}
.chrt-cal-heatmap-c--void{fill:none}
.chrt-cal-heatmap-c--sel{stroke:var(--ch-ink)}
.chrt-cal-heatmap-tip{
  position:absolute;left:0;top:0;pointer-events:none;white-space:nowrap;
  display:flex;flex-direction:column;gap:1px;padding:3px 7px;border-radius:7px;
  background:rgba(8,12,10,.95);border:1px solid rgba(255,255,255,.14);box-shadow:0 6px 16px rgba(0,0,0,.5);
  opacity:0;transform:translate(-50%,-124%) scale(.92);
  transition:opacity .15s,transform .18s cubic-bezier(.22,1,.36,1);
}
.chrt-cal-heatmap--tip .chrt-cal-heatmap-tip{opacity:1;transform:translate(-50%,-124%) scale(1)}
.chrt-cal-heatmap--down .chrt-cal-heatmap-tip{transform:translate(-50%,10%) scale(.92)}
.chrt-cal-heatmap--down.chrt-cal-heatmap--tip .chrt-cal-heatmap-tip{transform:translate(-50%,10%) scale(1)}
.chrt-cal-heatmap-tipv{font-size:10px;font-weight:700;color:var(--ch-l4);font-variant-numeric:tabular-nums}
.chrt-cal-heatmap-tipd{font-size:8.5px;color:var(--ch-dim)}
.chrt-cal-heatmap-legend{display:flex;align-items:center;justify-content:flex-end;gap:3px;margin-top:5px}
.chrt-cal-heatmap-lt{font-size:8px;color:var(--ch-dim);margin:0 2px}
.chrt-cal-heatmap-sw{width:8px;height:8px;border-radius:2px;display:block}
.chrt-cal-heatmap-sw--l0{background:var(--ch-l0)}
.chrt-cal-heatmap-sw--l1{background:var(--ch-l1)}
.chrt-cal-heatmap-sw--l2{background:var(--ch-l2)}
.chrt-cal-heatmap-sw--l3{background:var(--ch-l3)}
.chrt-cal-heatmap-sw--l4{background:var(--ch-l4)}
@media (prefers-reduced-motion:reduce){
  .chrt-cal-heatmap-c{opacity:1;transform:none;transition:stroke .15s}
  .chrt-cal-heatmap-tip{transition:none}
}

