var NS="http://www.w3.org/2000/svg";
var COLS=20,ROWS=7,CELL=8.6,PITCH=10.8,X0=22,Y0=12,VW=244,VH=92;
var MON=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
var DOW=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
var cells=root.querySelector(".chrt-cal-heatmap-cells");
var months=root.querySelector(".chrt-cal-heatmap-months");
var days=root.querySelector(".chrt-cal-heatmap-days");
var tip=root.querySelector(".chrt-cal-heatmap-tip");
var tipv=root.querySelector(".chrt-cal-heatmap-tipv");
var tipd=root.querySelector(".chrt-cal-heatmap-tipd");
var count=root.querySelector(".chrt-cal-heatmap-count");
var wrap=root.querySelector(".chrt-cal-heatmap-wrap");
function mk(t,cls,at){var e=document.createElementNS(NS,t);e.setAttribute("class",cls);for(var k in at){e.setAttribute(k,at[k]);}return e;}
var today=new Date();today.setHours(12,0,0,0);
var end=new Date(today);end.setDate(end.getDate()+(6-end.getDay()));
var start=new Date(end);start.setDate(start.getDate()-(COLS*ROWS-1));
function count4(d){
  var k=d.getFullYear()*372+d.getMonth()*31+d.getDate();
  var s=Math.abs(Math.sin(k*12.9898)*43758.5453);
  s=s-Math.floor(s);
  var wk=(d.getDay()===0||d.getDay()===6)?.35:1;
  return Math.round(Math.pow(s,2.6)*15*wk);
}
function lvl(c){return c===0?0:(c<3?1:(c<6?2:(c<10?3:4)));}
var list=[],total=0,lastMonth=-1,todayIdx=0;
for(var i=0;i<COLS*ROWS;i++){
  var d=new Date(start);d.setDate(start.getDate()+i);
  var col=Math.floor(i/7),row=i%7;
  var future=d>today;
  var c=future?0:count4(d);
  if(!future){total+=c;}
  var x=X0+col*PITCH,y=Y0+row*PITCH;
  var r=mk("rect",future?"chrt-cal-heatmap-c chrt-cal-heatmap-c--void":"chrt-cal-heatmap-c chrt-cal-heatmap-c--l"+lvl(c),
    {x:x,y:y,width:CELL,height:CELL,rx:2});
  r.style.setProperty("--i",col);
  cells.appendChild(r);
  list.push({el:r,d:d,c:c,x:x,y:y,future:future});
  if(!future){todayIdx=i;}
  if(row===0&&d.getMonth()!==lastMonth&&d.getDate()<=14){
    lastMonth=d.getMonth();
    var t=mk("text","chrt-cal-heatmap-t",{x:x,y:7});
    t.textContent=MON[d.getMonth()];
    months.appendChild(t);
  }
}
[1,3,5].forEach(function(r){
  var t=mk("text","chrt-cal-heatmap-t",{x:X0-5,y:Y0+r*PITCH+6.4,"text-anchor":"end"});
  t.textContent=DOW[r].charAt(0);
  days.appendChild(t);
});
count.textContent=total.toLocaleString("en-US")+" in 20 weeks";
var sel=-1;
function pick(i){
  if(i<0||i>=list.length||list[i].future){return;}
  if(sel>=0){list[sel].el.classList.remove("chrt-cal-heatmap-c--sel");}
  sel=i;
  var it=list[i];
  it.el.classList.add("chrt-cal-heatmap-c--sel");
  tipv.textContent=it.c===1?"1 deploy":it.c+" deploys";
  tipd.textContent=DOW[it.d.getDay()]+" "+it.d.getDate()+" "+MON[it.d.getMonth()];
  var down=(i%7)<2;
  root.classList.toggle("chrt-cal-heatmap--down",down);
  tip.style.left=((it.x+CELL/2)/VW*100)+"%";
  tip.style.top=((it.y+(down?CELL:0))/VH*100)+"%";
  root.classList.add("chrt-cal-heatmap--tip");
}
function clear(){
  if(sel>=0){list[sel].el.classList.remove("chrt-cal-heatmap-c--sel");}
  sel=-1;root.classList.remove("chrt-cal-heatmap--tip");
}
list.forEach(function(it,i){
  it.el.addEventListener("pointerenter",function(){pick(i);});
});
wrap.addEventListener("pointerleave",clear);
wrap.addEventListener("blur",clear);
wrap.addEventListener("focus",function(){if(sel<0){pick(todayIdx);}});
wrap.addEventListener("keydown",function(e){
  var i=sel<0?todayIdx:sel,k=e.key;
  if(k==="ArrowRight"){pick(Math.min(list.length-1,i+7));}
  else if(k==="ArrowLeft"){pick(Math.max(0,i-7));}
  else if(k==="ArrowDown"){pick(Math.min(list.length-1,i+1));}
  else if(k==="ArrowUp"){pick(Math.max(0,i-1));}
  else if(k==="Escape"){clear();}
  else{return;}
  e.preventDefault();
});
requestAnimationFrame(function(){root.classList.add("chrt-cal-heatmap--in");});
